  async function verifyAdmin(){

    const {
      data: sessionData,
      error: sessionError
    } =
      await supabaseClient.auth.getSession();

    if(sessionError){
      showLogin();
      return false;
    }

    const session =
      sessionData &&
      sessionData.session;

    if(!session){
      showLogin();
      return false;
    }

    const {
      data,
      error
    } =
      await supabaseClient.rpc(
        "is_site_admin"
      );

    if(error){
      console.error("SHOUFHON ADMIN: is_site_admin check failed:", error);

      showLogin();

      setStatus(
        loginStatus,
        "Could not verify admin access. Please try again.",
        "error"
      );

      return false;
    }

    if(data !== true){
      showLogin();

      setStatus(
        loginStatus,
        "This account is not a ShoufHon site admin.",
        "error"
      );

      return false;
    }

    showDashboard(
      session.user &&
      session.user.email
    );

    await loadExistingDirectoryValues();
    await loadManagedShops();
    await loadAdminActivity();

    // Tell merged admin tools that the SAME admin session is verified and ready.
    window.dispatchEvent(new CustomEvent("ma7alak:admin-ready"));

    return true;
  }


  async function loadExistingDirectoryValues(){

    const {
      data,
      error
    } =
      await supabaseClient
        .from("shop_profiles")
        .select(
          "area,category,category_name"
        )
        .eq("is_active", true);

    if(error){
      console.warn(
        "Could not load existing filters:",
        error
      );
      return;
    }

    const areas =
      Array.from(
        new Set(
          (data || [])
            .map(row => normalizedText(row.area))
            .filter(Boolean)
        )
      ).sort(
        (a,b) => a.localeCompare(b)
      );

    const categoriesMap =
      new Map();

    (data || []).forEach(row => {

      const category =
        normalizedText(row.category);

      if(!category){
        return;
      }

      const display =
        normalizedText(row.category_name);

      if(!categoriesMap.has(category)){
        categoriesMap.set(
          category,
          display
        );
      }
    });


    areaList.innerHTML =
      areas
        .map(area => {
          return (
            '<option value="' +
            escapeHtml(area) +
            '"></option>'
          );
        })
        .join("");


    categoryList.innerHTML =
      Array.from(categoriesMap.entries())
        .sort(
          (a,b) => a[0].localeCompare(b[0])
        )
        .map(([category, label]) => {

          const optionLabel =
            label
              ? ' label="' + escapeHtml(label) + '"'
              : "";

          return (
            '<option value="' +
            escapeHtml(category) +
            '"' +
            optionLabel +
            '></option>'
          );
        })
        .join("");
  }


  async function loadManagedShops(){

    setStatus(manageStatus, "Loading shops…");

    const useLegacyCards =
      window.__MA7ALAK_ADMIN_WORKSPACE_V4_BUNDLE__ !== true;

    const shopResult =
      await supabaseClient
        .from("shop_profiles")
        .select("*")
        .order("shop_name", { ascending:true });

    const { data, error } = shopResult;

    if(error){
      setStatus(manageStatus, error.message || "Could not load shops.", "error");
      return;
    }

    managedShops = data || [];

    if(useLegacyCards){
      const nowIso = new Date().toISOString();
      const storyResult =
        await supabaseClient
          .from("shop_stories")
          .select("shop_slug,expires_at");

      activeStoryShopSlugs = new Set(
        storyResult.error
          ? []
          : (storyResult.data || [])
              .filter(row => !row.expires_at || row.expires_at > nowIso)
              .map(row => String(row.shop_slug || ""))
              .filter(Boolean)
      );
    }else{
      activeStoryShopSlugs = new Set();
    }

    setStatus(manageStatus, "");
    renderManagedShops();
  }


  async function loadVisibleOwnerBadges(){

    const badges = Array.from(
      manageShopList.querySelectorAll("[data-owner-badge]")
    );

    for(const badge of badges){
      const slug = badge.getAttribute("data-owner-badge") || "";
      if(!slug) continue;

      try{
        const data = await invokeOwnerManager({
          action:"status",
          shop_slug:slug
        });

        if(data && data.owner_exists){
          badge.textContent = "Account Active";
          badge.classList.add("linked");
        }else{
          badge.textContent = "No Account";
          badge.classList.remove("linked");
        }
      }catch(error){
        console.warn("Owner badge failed for", slug, error);
        badge.textContent = "Owner status unavailable";
        badge.classList.remove("linked");
      }
    }
  }


  function getShopCompleteness(shop){

    const missing = [];

    if(!normalizedText(shop.shop_url)){
      missing.push("shop URL");
    }

    if(!normalizedText(shop.category)){
      missing.push("category ID");
    }

    if(!normalizedText(shop.category_name)){
      missing.push("category name");
    }

    if(!normalizedText(shop.location)){
      missing.push("location");
    }

    return {
      ready: missing.length === 0,
      missing: missing
    };
  }


  function completenessMessage(result){
    if(result.ready){
      return "";
    }

    return "Missing: " + result.missing.join(", ");
  }



  async function requireGalleryAdmin(){

    const { data, error } =
      await supabaseClient.rpc("is_site_admin");

    if(error || data !== true){
      throw new Error("Admin session is no longer valid. Login again.");
    }

    return true;
  }


  function cleanGalleryFileName(name){

    const raw = String(name || "image")
      .toLowerCase()
      .replace(/\.[^/.]+$/, "")
      .replace(/[^a-z0-9_-]+/g, "-")
      .replace(/-+/g, "-")
      .replace(/^-|-$/g, "")
      .slice(0, 70);

    return raw || "image";
  }


  function galleryExtension(file){

    const fromName =
      String(file && file.name || "")
        .split(".")
        .pop()
        .toLowerCase();

    if(["jpg","jpeg","png","webp","gif"].includes(fromName)){
      return fromName === "jpeg" ? "jpg" : fromName;
    }

    const mime = String(file && file.type || "").toLowerCase();

    if(mime === "image/png") return "png";
    if(mime === "image/webp") return "webp";
    if(mime === "image/gif") return "gif";

    return "jpg";
  }


