  async function publishLiveReel(){
    const slug =
      normalizedText(reelsShopSlug.value);

    const videoUrl =
      normalizedText(reelsVideoUrl.value);

    const caption =
      normalizedText(reelsCaption.value);

    if(!slug){
      setStatus(
        reelsStatus,
        "No shop selected.",
        "error"
      );
      return;
    }

    if(!/^https?:\/\//i.test(videoUrl)){
      setStatus(
        reelsStatus,
        "Enter a valid direct video URL.",
        "error"
      );
      return;
    }

    const shop =
      currentReelsShop ||
      getManagedShop(slug);

    if(!shop){
      setStatus(
        reelsStatus,
        "Could not find this shop.",
        "error"
      );
      return;
    }

    reelsPublishButton.disabled =
      true;

    reelsPublishButton.textContent =
      "Publishing…";

    try{
      await requireReelsAdmin();

      const sortOrder =
        await nextReelSortOrder();

      const reelId =
        makeReelId(slug);

      const shopName =
        normalizedText(
          shop.shop_name ||
          slug
        );

      const shopUrl =
        normalizedText(
          shop.shop_url ||
          ("https://shoufhon.com/" + encodeURIComponent(slug))
        );

      const shopIcon =
        normalizedText(
          shop.profile_image_url || ""
        );

      const { error } =
        await supabaseClient
          .from("shop_reels")
          .insert({
            reel_id:reelId,
            shop_slug:slug,
            shop_name:shopName,
            shop_url:shopUrl,
            shop_icon:shopIcon,
            video_url:videoUrl,
            caption:caption,
            sort_order:sortOrder,
            active:true
          });

      if(error) throw error;

      await logAdminActivity(
        "reel_published",
        slug,
        {
          reel_id:reelId,
          source:pendingReelStoragePath ? "device_upload" : "direct_url"
        }
      );

      pendingReelStoragePath =
        "";

      pendingReelPublicUrl =
        "";

      reelsFileInput.value =
        "";

      reelsVideoUrl.value =
        "";

      reelsCaption.value =
        "";

      setStatus(
        reelsStatus,
        "Reel published LIVE successfully.",
        "success"
      );

      await loadReelItems();
    }
    catch(error){
      setStatus(
        reelsStatus,
        error.message || "Could not publish Reel.",
        "error"
      );
    }
    finally{
      reelsPublishButton.disabled =
        false;

      reelsPublishButton.textContent =
        "Publish Live Reel";
    }
  }


  async function deleteLiveReel(reelId){
    const slug =
      normalizedText(reelsShopSlug.value);

    if(!slug || !reelId){
      return;
    }

    await requireReelsAdmin();

    const { data:reelRow, error:loadError } =
      await supabaseClient
        .from("shop_reels")
        .select("reel_id,video_url")
        .eq("reel_id", reelId)
        .eq("shop_slug", slug)
        .maybeSingle();

    if(loadError) throw loadError;

    const storagePath =
      reelRow
        ? getReelStoragePathFromUrl(reelRow.video_url)
        : "";

    if(storagePath && storagePath.indexOf("reels/") === 0){
      const { error:storageError } = await supabaseClient
        .storage
        .from("shop-videos")
        .remove([storagePath]);

      if(storageError){
        throw storageError;
      }
    }

    const { error } =
      await supabaseClient
        .from("shop_reels")
        .delete()
        .eq("reel_id", reelId)
        .eq("shop_slug", slug);

    if(error) throw error;
  }


  function renderManagedShops(){

    /*
       Workspace V4 fully replaces the old Manage Shops card list.
       Keep managedShops data alive for core editor/media compatibility,
       but do not build duplicate hidden shop-card DOM.
    */
    if(window.__MA7ALAK_ADMIN_WORKSPACE_V4_BUNDLE__ === true){
      if(manageShopList){
        manageShopList.replaceChildren();
      }

      if(manageShopCount){
        manageShopCount.textContent =
          managedShops.length +
          (managedShops.length === 1 ? " shop" : " shops");
      }

      return;
    }

    const term = normalizedText(manageShopSearch.value).toLowerCase();

    const rows = managedShops.filter(function(shop){
      if(!term) return true;
      return [shop.shop_name, shop.arabic_name, shop.shop_slug, shop.city, shop.area, shop.category_name, shop.location]
        .some(function(value){
          return String(value || "").toLowerCase().includes(term);
        });
    });

    manageShopCount.textContent = rows.length + (rows.length === 1 ? " shop" : " shops");

    if(!rows.length){
      manageShopList.innerHTML = '<div class="ma-admin-empty">No shops found.</div>';
      return;
    }

    manageShopList.innerHTML = rows.map(function(shop){

      const slug = escapeHtml(shop.shop_slug || "");
      const name = escapeHtml(shop.shop_name || shop.shop_slug || "Shop");
      const image = escapeHtml(shop.profile_image_url || "");
      const directoryOptions = shop.directory_options && typeof shop.directory_options === "object" ? shop.directory_options : {};
      const cover = escapeHtml(directoryOptions.cover || shop.main_image_url || shop.intro_poster_url || "");
      const directoryBadge = normalizedText(directoryOptions.badge);
      const featuredUntil = directoryOptions.featured_until ? new Date(directoryOptions.featured_until) : null;
      const featureActive = shop.featured === true && (!featuredUntil || featuredUntil > new Date());
      const featureDays = featuredUntil && featuredUntil > new Date()
        ? Math.max(1, Math.ceil((featuredUntil.getTime() - Date.now()) / 86400000))
        : null;
      const hasStory = activeStoryShopSlugs.has(String(shop.shop_slug || ""));
      const meta = [shop.city, shop.area, shop.category_name || shop.category, shop.location].filter(Boolean).map(escapeHtml).join(" • ");

      const imageHtml = image
        ? '<img src="' + image + '" alt="" loading="lazy" onerror="this.parentNode.innerHTML=\'<div class=&quot;ma-admin-shop-thumb-fallback&quot;>🏪</div>\'">'
        : '<div class="ma-admin-shop-thumb-fallback">🏪</div>';

      const completeness = getShopCompleteness(shop);
      const completenessText = completeness.ready
        ? ""
        : completenessMessage(completeness);

      let badges = '';
      badges += '<span class="ma-admin-shop-badge ' + (shop.is_active ? 'active' : '') + '">' + (shop.is_active ? 'Active' : 'Hidden') + '</span>';
      badges += '<span class="ma-admin-shop-badge ' + (shop.verified ? 'verified' : 'incomplete') + '">' + (shop.verified ? '✓ Verified' : 'Not verified') + '</span>';
      if(hasStory) badges += '<span class="ma-admin-shop-badge live">● LIVE</span>';
      if(featureActive) badges += '<span class="ma-admin-shop-badge featured">Featured' + (featureDays ? ' · ' + featureDays + 'd' : '') + '</span>';
      if(directoryBadge) badges += '<span class="ma-admin-shop-badge new">' + escapeHtml(directoryBadge) + '</span>';

      const completenessNote = completeness.ready
        ? ''
        : '<div class="ma-admin-completeness-note">' + escapeHtml(completenessText) + '</div>';

      return '' +
        '<article class="ma-admin-shop-item ' + (shop.is_active ? '' : 'is-inactive') + '" data-slug="' + slug + '">' +
          (cover ? '<img class="ma-admin-shop-cover" src="' + cover + '" alt="" loading="lazy">' : '') +
          '<div class="ma-admin-shop-thumb ' + (hasStory ? 'has-story' : '') + '" style="--shop-story-color:' + (/^#[0-9a-f]{6}$/i.test(String(directoryOptions.story_color || '')) ? escapeHtml(directoryOptions.story_color) : '#e3b85f') + '">' + imageHtml + '</div>' +
          '<div class="ma-admin-shop-info">' +
            '<div class="ma-admin-shop-name-row"><div class="ma-admin-shop-name">' + name + '</div></div>' +
            '<div class="ma-admin-shop-slug">/' + slug + '</div>' +
            '<div class="ma-admin-shop-meta">' + meta + '</div>' +
            '<div class="ma-admin-shop-badges">' + badges + '</div>' +
            completenessNote +
          '</div>' +
          '<div class="ma-admin-shop-actions">' +
            '<button class="ma-shop-action primary" type="button" data-action="edit">✏️ Edit all</button>' +
            '<button class="ma-shop-action" type="button" data-action="active">' + (shop.is_active ? '🙈 Hide shop' : '👁 Show shop') + '</button>' +
            '<button class="ma-shop-action verify" type="button" data-action="verified">' + (shop.verified ? '✓ Unverify' : '✓ Verify') + '</button>' +
            '<button class="ma-shop-action feature" type="button" data-action="featured">' + (featureActive ? '★ Unfeature' : '☆ Feature days') + '</button>' +
            '<button class="ma-shop-action new" type="button" data-action="new">' + (/^new$/i.test(directoryBadge) ? 'Remove NEW' : '＋ NEW badge') + '</button>' +
            '<button class="ma-shop-action gallery" type="button" data-action="gallery">🖼 Gallery</button>' +
            '<button class="ma-shop-action video" type="button" data-action="video">🎥 Videos</button>' +
            '<button class="ma-shop-action feature" type="button" data-action="reels">🔥 Reels</button>' +
            '<button class="ma-shop-action" type="button" data-action="view">↗ View shop</button>' +
            '<button class="ma-shop-action danger" type="button" data-action="delete">Delete</button>' +
          '</div>' +
        '</article>';
    }).join("");
  }


  async function invokeOwnerManager(body){

    const { data: adminCheck, error: adminError } =
      await supabaseClient.rpc("is_site_admin");

    if(adminError || adminCheck !== true){
      throw new Error("Admin session is no longer valid. Login again.");
    }

    const { data, error } =
      await supabaseClient.functions.invoke("create-shop-owner", {
        body: body
      });

    if(error){
      let message = error.message || "Owner management request failed.";

      if(error.context && typeof error.context.json === "function"){
        try{
          const errorBody = await error.context.json();
          if(errorBody && errorBody.error){
            message = errorBody.error;
          }
        }catch(_){}
      }

      throw new Error(message);
    }

    if(!data || data.success !== true){
      throw new Error(
        data && data.error
          ? data.error
          : "Owner management request failed."
      );
    }

    return data;
  }


