  async function uploadNewShopProfileImage(slug){
    if(!shopImageFile || !shopImageFile.files || !shopImageFile.files[0]){
      return "";
    }

    const file = shopImageFile.files[0];

    if(!/^image\/(jpeg|png|webp|gif)$/i.test(file.type || "")){
      throw new Error("Profile image must be JPG, PNG, WEBP or GIF.");
    }

    const maxBytes = 12 * 1024 * 1024;
    if(file.size > maxBytes){
      throw new Error("Profile image must be smaller than 12 MB.");
    }

    const ext =
      ((file.name || "").split(".").pop() || "jpg")
        .toLowerCase()
        .replace(/[^a-z0-9]/g,"") || "jpg";

    const storagePath =
      "profiles/" +
      slug +
      "/" +
      Date.now() +
      "-" +
      Math.random().toString(36).slice(2,8) +
      "." +
      ext;

    const { error:uploadError } =
      await supabaseClient
        .storage
        .from("shop-gallery")
        .upload(storagePath, file, {
          cacheControl:"31536000",
          upsert:false,
          contentType:file.type || undefined
        });

    if(uploadError) throw uploadError;

    const { data:publicData } =
      supabaseClient
        .storage
        .from("shop-gallery")
        .getPublicUrl(storagePath);

    return publicData && publicData.publicUrl
      ? publicData.publicUrl
      : "";
  }

  shopForm.addEventListener(
    "submit",
    async function(event){

      event.preventDefault();

      setStatus(
        shopStatus,
        ""
      );

      const slug =
        normalizeSlug(
          shopSlug.value
        );

      const name =
        normalizedText(
          shopName.value
        );

      const area =
        "";

      const category =
        normalizedText(
          shopCategory.value
        );

      const categoryName =
        normalizedText(
          shopCategoryName.value
        );

      const selectedCity =
        normalizedText(
          document.getElementById("ma-shop-city-v2") &&
          document.getElementById("ma-shop-city-v2").value
        );

      if(
        !slug ||
        !name ||
        !selectedCity ||
        !category
      ){
        setStatus(
          shopStatus,
          "Fill all required fields first.",
          "error"
        );
        return;
      }

      const selectedTaxonomyCategory =
        (window.__MA7ALAK_V2_CATEGORIES__ || []).find(function(row){
          return row && row.category_key === category;
        });

      const finalCardLabel =
        categoryName ||
        (selectedTaxonomyCategory && selectedTaxonomyCategory.category_name) ||
        category;

      addShopButton.disabled = true;
      addShopButton.innerHTML =
        "Adding shop…";

      try{

        const {
          data: adminCheck,
          error: adminError
        } =
          await supabaseClient.rpc(
            "is_site_admin"
          );

        if(
          adminError ||
          adminCheck !== true
        ){
          throw new Error(
            "Admin session is no longer valid. Login again."
          );
        }

        const finalShopUrl =
          normalizedText(
            shopUrl.value
          ) ||
          (
            "https://shoufhon.com/" +
            slug
          );

        const uploadedProfileImage =
          await uploadNewShopProfileImage(slug);

        const payload = {
          ...window.Ma7alakDirectoryAdmin.collect(false),
          shop_slug: slug,
          shop_name: name,
          arabic_name:
            normalizedText(
              shopArabic.value
            ) || null,
          profile_image_url:
            uploadedProfileImage ||
            normalizedText(
              shopImage.value
            ) ||
            null,
          shop_url:
            finalShopUrl,
          city:
            selectedCity || null,
          area:
            area,
          category:
            category,
          category_name:
            finalCardLabel,
          location:
            normalizedText(
              shopLocation.value
            ) || null,
          verified:
            shopVerified.checked,
          featured:
            shopFeatured.checked,
          featured_red:
            shopRed.checked,
          is_active:
            shopActive.checked
        };

        if(payload.is_active){
          const completeness = getShopCompleteness(payload);

          if(!completeness.ready){
            throw new Error(
              "Cannot publish this shop yet. " + completenessMessage(completeness) + ". Turn Active OFF to save it as hidden, or complete those fields first."
            );
          }
        }

        const {
          error
        } =
          await supabaseClient
            .from("shop_profiles")
            .insert(payload);

        if(error){

          if(
            error.code === "23505"
          ){
            throw new Error(
              'A shop with slug "' +
              slug +
              '" already exists. Nothing was overwritten.'
            );
          }

          throw error;
        }

        await logAdminActivity(
          "shop_added",
          slug,
          { shop_name: name }
        );
        loadAdminActivity();

        setStatus(
          shopStatus,
          'Shop "' +
          name +
          '" was added successfully. It can now appear automatically in Full Shops.',
          "success"
        );

        lastAddedShopSlug = slug;
        postAddOwnerTitle.textContent = name + " was added";
        postAddOwner.hidden = false;

        shopForm.reset();

        shopActive.checked = true;

        shopSlug.dataset.manual = "";
        shopUrl.dataset.auto = "";

        imagePreviewWrap.hidden = true;
        imagePreview.removeAttribute("src");

        updatePreview();

        await loadExistingDirectoryValues();
        await loadManagedShops();

        window.scrollTo({
          top:
            document.getElementById(
              "ma-admin-dashboard"
            ).offsetTop,
          behavior:"smooth"
        });

      }catch(error){

        console.error(
          "Add shop failed:",
          error
        );

        setStatus(
          shopStatus,
          error &&
          error.message
            ? error.message
            : "Could not add shop.",
          "error"
        );

      }finally{

        addShopButton.disabled = false;

        addShopButton.innerHTML =
          "<span>＋</span> Add Shop";
      }
    }
  );


