  function bannerShopSlug(prefix){
    const raw =
      prefix === "m7de-"
        ? document.getElementById("ma-edit-original-slug")?.value
        : document.getElementById("ma-shop-slug")?.value;

    return String(raw || "")
      .trim()
      .toLowerCase()
      .replace(/[^a-z0-9-]+/g,"-")
      .replace(/-+/g,"-")
      .replace(/^-|-$/g,"");
  }

  async function uploadProfileBanner(prefix,file,box){
    if(!file){
      return "";
    }

    const slug =
      bannerShopSlug(prefix);

    if(!slug){
      throw new Error(
        prefix === "m7de-"
          ? "No shop selected."
          : "Enter the Shop Slug first, then choose the banner image."
      );
    }

    if(!/^image\/(jpeg|png|webp|gif)$/i.test(file.type || "")){
      throw new Error(
        "Banner image must be JPG, PNG, WEBP or GIF."
      );
    }

    if(file.size > 12 * 1024 * 1024){
      throw new Error(
        "Banner image must be smaller than 12 MB."
      );
    }

    const client =
      window.Ma7alakAdminClient;

    if(
      !client ||
      !client.storage
    ){
      throw new Error(
        "Admin storage is still loading. Try again."
      );
    }

    const adminCheck =
      await client.rpc(
        "is_site_admin"
      );

    if(
      adminCheck.error ||
      adminCheck.data !== true
    ){
      throw new Error(
        "Admin session is no longer valid. Login again."
      );
    }

    const ext =
      (
        String(file.name || "")
          .split(".")
          .pop() ||
        "jpg"
      )
        .toLowerCase()
        .replace(/[^a-z0-9]/g,"") ||
      "jpg";

    const storagePath =
      "profile-banners/" +
      slug +
      "/" +
      Date.now() +
      "-" +
      Math.random()
        .toString(36)
        .slice(2,8) +
      "." +
      ext;

    const upload =
      await client
        .storage
        .from("shop-gallery")
        .upload(
          storagePath,
          file,
          {
            cacheControl:"31536000",
            upsert:false,
            contentType:file.type || undefined
          }
        );

    if(upload.error){
      throw upload.error;
    }

    const publicData =
      client
        .storage
        .from("shop-gallery")
        .getPublicUrl(
          storagePath
        );

    const publicUrl =
      publicData &&
      publicData.data &&
      publicData.data.publicUrl
        ? publicData.data.publicUrl
        : "";

    if(!publicUrl){
      throw new Error(
        "Could not create the public banner URL."
      );
    }

    return publicUrl;
  }

  async function uploadProfileShellBackground(prefix,file,box){
    if(!file){
      return "";
    }

    const slug=
      bannerShopSlug(prefix);

    if(!slug){
      throw new Error(
        prefix === "m7de-"
          ? "No shop selected."
          : "Enter the Shop Slug first, then choose the profile background image."
      );
    }

    if(!/^image\/(jpeg|png|webp|gif)$/i.test(file.type || "")){
      throw new Error(
        "Profile background must be JPG, PNG, WEBP or GIF."
      );
    }

    if(file.size > 12 * 1024 * 1024){
      throw new Error(
        "Profile background must be smaller than 12 MB."
      );
    }

    const client=
      window.Ma7alakAdminClient;

    if(!client || !client.storage){
      throw new Error(
        "Admin storage is still loading. Try again."
      );
    }

    const adminCheck=
      await client.rpc("is_site_admin");

    if(adminCheck.error || adminCheck.data !== true){
      throw new Error(
        "Admin session is no longer valid. Login again."
      );
    }

    const ext=(
      String(file.name || "")
        .split(".")
        .pop() ||
      "jpg"
    )
      .toLowerCase()
      .replace(/[^a-z0-9]/g,"") ||
      "jpg";

    const storagePath=
      "profile-shell-backgrounds/" +
      slug +
      "/" +
      Date.now() +
      "-" +
      Math.random().toString(36).slice(2,8) +
      "." +
      ext;

    const upload=
      await client
        .storage
        .from("shop-gallery")
        .upload(
          storagePath,
          file,
          {
            cacheControl:"31536000",
            upsert:false,
            contentType:file.type || undefined
          }
        );

    if(upload.error){
      throw upload.error;
    }

    const publicData=
      client
        .storage
        .from("shop-gallery")
        .getPublicUrl(storagePath);

    const publicUrl=
      publicData &&
      publicData.data &&
      publicData.data.publicUrl
        ? publicData.data.publicUrl
        : "";

    if(!publicUrl){
      throw new Error(
        "Could not create the public profile background URL."
      );
    }

    return publicUrl;
  }

