    bannerFile?.addEventListener(
      "change",
      async function(){

        const file =
          bannerFile.files &&
          bannerFile.files[0];

        if(!file){
          return;
        }

        bannerFile.disabled = true;

        if(bannerStatus){
          bannerStatus.textContent =
            "Uploading banner…";
        }

        try{
          const url =
            await uploadProfileBanner(
              prefix,
              file,
              box
            );

          if(bannerUrl){
            bannerUrl.value =
              url;

            bannerUrl.dispatchEvent(
              new Event(
                "input",
                {bubbles:true}
              )
            );
          }

          if(bannerEnabled){
            bannerEnabled.checked =
              true;

            bannerEnabled.dispatchEvent(
              new Event(
                "change",
                {bubbles:true}
              )
            );
          }

          if(bannerStatus){
            bannerStatus.textContent =
              "Uploaded — press Save Changes to apply.";
          }

          refreshBannerPreview();
        }
        catch(error){
          if(bannerStatus){
            bannerStatus.textContent =
              error &&
              error.message
                ? error.message
                : "Banner upload failed.";
          }
        }
        finally{
          bannerFile.disabled = false;
          bannerFile.value = "";
        }
      }
    );

