  function fillForm(prefix,options){
    const accent =
      safeHex(
        options.story_color ||
        options.card_color,
        "#f2caed"
      );

    const values = Object.assign({},DEFAULTS,options);

    COLORS.forEach(([key])=>{
      values[key] =
        safeHex(
          options[key],
          key.includes("_bg_") ||
          key.endsWith("_bg_color") ||
          key === "profile_banner_color"
            ? DEFAULTS[key]
            : accent
        );
    });

    Object.keys(DEFAULTS).forEach(key=>{
      const el =
        document.getElementById(
          prefix + key
        );

      if(!el){
        return;
      }

      if(el.type === "checkbox"){
        el.checked =
          options[key] === undefined
            ? !!DEFAULTS[key]
            : !!options[key];
      }
      else{
        el.value =
          values[key] === undefined ||
          values[key] === null
            ? DEFAULTS[key]
            : String(values[key]);
      }
    });

    document
      .getElementById(prefix+"page_design_preset")
      ?.closest(".m7-design-studio")
      ?.__m7dsRefresh?.();
  }

  function collectForm(prefix,result){
    result.directory_options =
      result.directory_options &&
      typeof result.directory_options === "object"
        ? result.directory_options
        : {};

    const options =
      result.directory_options;

    Object.keys(DEFAULTS).forEach(key=>{
      const el =
        document.getElementById(
          prefix + key
        );

      if(!el){
        return;
      }

      if(el.type === "checkbox"){
        options[key] = !!el.checked;
      }
      else if(el.type === "color"){
        options[key] =
          safeHex(
            el.value,
            DEFAULTS[key]
          );
      }
      else if(el.type === "number"){
        const number =
          Math.max(
            Number(el.min || 0),
            Math.min(
              Number(el.max || 9999),
              Number(el.value || DEFAULTS[key])
            )
          );

        options[key] =
          String(
            Number.isFinite(number)
              ? number
              : DEFAULTS[key]
          );
      }
      else{
        options[key] =
          String(el.value || "").trim();
      }
    });

    return result;
  }

  function patch(){
    if(patched){
      return;
    }

    const api =
      window.Ma7alakDirectoryAdmin;

    if(
      !api ||
      typeof api.fill !== "function" ||
      typeof api.collect !== "function"
    ){
      return;
    }

    patched = true;

    const oldFill =
      api.fill.bind(api);

    const oldCollect =
      api.collect.bind(api);

    api.fill = function(shop){
      oldFill(shop);
      mountAll();

      const options =
        shop &&
        shop.directory_options &&
        typeof shop.directory_options === "object"
          ? shop.directory_options
          : {};

      fillForm(
        "m7de-",
        options
      );
    };

    api.collect = function(edit){
      const result =
        oldCollect(edit);

      return collectForm(
        edit ? "m7de-" : "m7da-",
        result
      );
    };
  }

