function markLegacyPanels(){
  PANEL_IDS.forEach(id=>{
    const el=document.getElementById(id);
    if(el)el.classList.add("m7v4-legacy-panel");
  });
}

function closeV4Panel(panel){
  if(!panel)return;

  const id=panel.id||"";

  const nativeClose={
    "ma-admin-edit-card":"ma-admin-cancel-edit",
    "ma-admin-gallery-card":"ma-gallery-close",
    "ma-admin-video-card":"ma-video-close",
    "ma-admin-reels-card":"ma-reels-close"
  }[id];

  if(nativeClose){
    document.getElementById(nativeClose)?.click();
  }

  if(id==="m7adm-v3"){
    panel.querySelectorAll(".m7adm-body").forEach(body=>{
      body.hidden=true;
      body.classList.add("hidden");
    });

    panel.querySelectorAll(".m7adm-tab").forEach(tab=>{
      tab.classList.remove("active");
      tab.setAttribute("aria-selected","false");
    });

    window.dispatchEvent(
      new CustomEvent(
        "ma7alak:admin-tool-visibility",
        {detail:{target:"",open:false}}
      )
    );

    panel.scrollIntoView({behavior:"smooth",block:"start"});
    return;
  }

  if(id==="ma-manage-shops-card"){
    panel.classList.remove("m7v4-show-add");
    const drawer=document.getElementById("ma-admin-shop-form")?.closest(".m7sc-add-drawer");
    if(drawer)drawer.open=false;
  }

  panel.classList.remove(
    "m7v4-show",
    "m7v4-mode-details",
    "m7v4-mode-about",
    "m7v4-mode-hours",
    "m7v4-mode-label",
    "m7v4-mode-card",
    "m7v4-mode-design"
  );

  if(id!=="ma-manage-shops-card"){
    panel.hidden=true;
  }

  if(id==="ma-admin-edit-card"){
    document.getElementById("m7savebar")?.classList.remove("on");
  }
}

function ensurePanelCloseButton(panel){
  if(!panel||panel.querySelector(":scope > .m7v4-panel-close"))return;

  const button=document.createElement("button");
  button.type="button";
  button.className="m7v4-panel-close";
  button.setAttribute("aria-label","Close");
  button.title="Close";
  button.textContent="×";
  button.addEventListener("click",event=>{
    event.preventDefault();
    event.stopPropagation();
    closeV4Panel(panel);
  });

  panel.prepend(button);
}

function ensureAdminToolsFooter(){
  const dashboard=document.getElementById("ma-admin-dashboard");
  const tools=document.getElementById("m7adm-v3");

  if(!dashboard||!tools)return;

  tools.hidden=false;
  tools.removeAttribute("hidden");
  tools.classList.remove(
    "m7hidden",
    "m7collapsed",
    "m7-admin-collapsed",
    "m7v4-legacy-panel"
  );
  tools.classList.add("m7v4-admin-footer");

  const historyHost=
    tools.querySelector("[data-m7adm-history-host]");

  const historyCard=
    document.getElementById("ma-admin-activity-card");

  if(
    historyHost &&
    historyCard &&
    !historyHost.contains(historyCard)
  ){
    historyCard.hidden=false;
    historyCard.removeAttribute("hidden");
    historyCard.classList.remove(
      "m7v4-legacy-panel",
      "m7v4-show",
      "m7hidden",
      "m7collapsed",
      "m7-admin-collapsed"
    );
    historyHost.replaceChildren(historyCard);
  }

  ensurePanelCloseButton(tools);

  if(dashboard.lastElementChild!==tools){
    dashboard.appendChild(tools);
  }
}

function clearLegacy(){
  window.dispatchEvent(new CustomEvent("ma7alak:admin-tool-visibility",{detail:{target:"",open:false}}));
  document.querySelectorAll(".m7v4-legacy-panel").forEach(el=>{
    el.classList.remove(
      "m7v4-show",
      "m7v4-mode-details",
      "m7v4-mode-about",
      "m7v4-mode-hours",
      "m7v4-mode-label",
      "m7v4-mode-card",
      "m7v4-mode-design"
    );
  });

  document.getElementById("ma-manage-shops-card")?.classList.remove("m7v4-show-add");
}

function showLegacy(id){
  markLegacyPanels();
  clearLegacy();
  const el=document.getElementById(id);
  if(!el)return null;
  el.hidden=false;
  el.removeAttribute("hidden");
  el.classList.add("m7v4-show");
  ensurePanelCloseButton(el);
  setTimeout(()=>el.scrollIntoView({behavior:"smooth",block:"start"}),60);
  return el;
}

async function openAdminHub(target,shopSlug){
  let root=null;

  for(let i=0;i<60;i++){
    root=document.getElementById("m7adm-v3");
    if(root)break;
    await new Promise(resolve=>setTimeout(resolve,50));
  }

  if(!root){
    throw new Error("Admin Tools are still loading.");
  }

  markLegacyPanels();
  clearLegacy();
  ensureAdminToolsFooter();

  root.hidden=false;
  root.removeAttribute("hidden");
  root.classList.remove(
    "m7hidden",
    "m7collapsed",
    "m7-admin-collapsed"
  );
  root.classList.add("m7v4-admin-footer");
  ensurePanelCloseButton(root);

  const bodies=[
    ...root.querySelectorAll(".m7adm-body")
  ];

  const tabs=[
    ...root.querySelectorAll(".m7adm-tab")
  ];

  bodies.forEach(body=>{
    body.hidden=true;
    body.classList.add("hidden");
  });

  tabs.forEach(tab=>{
    tab.classList.remove("active");
    tab.setAttribute("aria-selected","false");
  });

  const body=document.getElementById(target);
  const tab=root.querySelector(
    '.m7adm-tab[data-target="'+CSS.escape(target)+'"]'
  );

  if(!body){
    throw new Error("This Admin Tool is not available.");
  }

  body.hidden=false;
  body.classList.remove("hidden");

  if(tab){
    tab.classList.add("active");
    tab.setAttribute("aria-selected","true");
  }

  if(target==="m7adm-history"){
    document.getElementById("ma-admin-activity-card")?.removeAttribute("hidden");
    setTimeout(
      ()=>document.getElementById("ma-admin-refresh-activity")?.click(),
      0
    );
  }

  if(
    target==="m7adm-owner" &&
    shopSlug
  ){
    const select=
      document.getElementById(
        "m7adm-owner-shop"
      );

    if(select){
      const wanted=
        String(shopSlug).trim();

      const hasOption=[
        ...select.options
      ].some(option=>
        String(option.value).trim()===
        wanted
      );

      if(hasOption){
        select.value=wanted;
        select.dispatchEvent(
          new Event(
            "change",
            {bubbles:true}
          )
        );
      }
    }
  }

  window.dispatchEvent(new CustomEvent("ma7alak:admin-tool-visibility",{detail:{target:target,open:true}}));

  setTimeout(()=>{
    root.scrollIntoView({
      behavior:"smooth",
      block:"start"
    });
  },60);

  return root;
}

async function waitForEdit(slug){
  for(let i=0;i<80;i++){
    const original=document.getElementById("ma-edit-original-slug");
    const card=document.getElementById("ma-admin-edit-card");
    if(original&&norm(original.value)===norm(slug)&&card&&!card.hidden)return card;
    await new Promise(resolve=>setTimeout(resolve,60));
  }
  return document.getElementById("ma-admin-edit-card");
}

function directFormChild(form,node){
  if(!form||!node)return null;

  let current=node;

  while(
    current &&
    current.parentElement &&
    current.parentElement!==form
  ){
    current=current.parentElement;
  }

  return current &&
    current.parentElement===form
      ? current
      : null;
}

function expandFocusedSection(node){
  if(!node)return;

  node.classList.remove(
    "m7fc"
  );

  const fold=
    node.querySelector(
      ":scope > .m7ft"
    );

  if(fold){
    fold.textContent="Fold";
  }
}

function editorModeMeta(mode,shop){
  const map={
    details:[
      "Shop Details",
      "Basic identity, location, category and profile information."
    ],
    label:[
      "Shop Label",
      "Only the label visitors see above the shop name."
    ],
    card:[
      "Directory Card",
      "Only the card appearance used in Show Shops."
    ],
    design:[
      "Profile Design",
      "Choose one design tab below. Only that design section is shown."
    ],
    about:[
      "About Me",
      "Only description, services, signature and About typography."
    ],
    hours:[
      "Hours & Availability",
      "Only weekly opening hours and availability."
    ]
  };

  const row=
    map[mode]||
    map.details;

  return {
    title:row[0],
    help:row[1],
    shopName:
      shop?.shop_name||
      shop?.shop_slug||
      "Shop"
  };
}

function ensureEditContext(form){
  let box=
    form.querySelector(
      ":scope > .m7v4-edit-context"
    );

  if(box)return box;

  box=document.createElement("div");
  box.className="m7v4-edit-context";
  box.innerHTML=
    '<div class="m7v4-edit-context-copy">'+
      '<small>SHOUFHON EDITOR</small>'+
      '<b data-m7v4-context-title>Editing</b>'+
      '<span data-m7v4-context-help></span>'+
    '</div>';

  form.insertBefore(
    box,
    form.firstChild
  );

  return box;
}

function updateEditContext(panel,mode,shop){
  const form=
    panel?.querySelector(
      "#ma-admin-edit-form"
    );

  if(!form)return;

  const box=
    ensureEditContext(form);

  const meta=
    editorModeMeta(
      mode,
      shop
    );

  let section="";

  if(mode==="design"){
    const active=
      form.querySelector(
        ".m7-design-studio [data-m7ds-tab].active"
      );

    if(active){
      section=
        " — "+
        String(
          active.textContent||
          ""
        ).trim();
    }
  }

  const title=
    box.querySelector(
      "[data-m7v4-context-title]"
    );

  if(title){
    title.textContent=
      "Editing: "+
      meta.title+
      section+
      " — "+
      meta.shopName;
  }

  const help=
    box.querySelector(
      "[data-m7v4-context-help]"
    );

  if(help){
    help.textContent=
      meta.help;
  }

  const subtitle=
    document.getElementById(
      "ma-admin-edit-subtitle"
    );

  if(subtitle){
    subtitle.textContent=
      "Editing: "+
      meta.title+
      " — "+
      meta.shopName;
  }
}

function hideDuplicatePublishingControls(form){
  if(!form)return;

  [
    "ma-edit-verified",
    "ma-edit-featured",
    "ma-edit-red",
    "ma-edit-active"
  ].forEach(id=>{
    const input=
      document.getElementById(id);

    if(!input)return;

    const wrapper=
      input.closest(
        "label,.ma-admin-switch,.ma-admin-toggle,.ma-admin-check"
      ) ||
      input.parentElement;

    if(wrapper){
      wrapper.classList.add(
        "m7v4-publishing-duplicate"
      );
    }
  });
}

function hideDuplicateDesignControls(form){
  if(!form)return;

  /*
     These exact colors already have richer controls in
     "Aa About — individual text styling".
     Keep the Page Design inputs alive and synchronized internally,
     but don't show the same setting twice to the admin.
  */
  [
    "m7de-about_title_color",
    "m7de-about_kicker_color",
    "m7de-about_text_color",
    "m7de-about_signature_color"
  ].forEach(id=>{
    const input=
      document.getElementById(id);

    const wrapper=
      input?.closest(
        ".m7ds-field"
      );

    if(wrapper){
      wrapper.classList.add(
        "m7v4-duplicate-control"
      );
    }
  });
}

function configureLegacyExtras(form,mode){
  if(!form)return;

  const box=
    form.querySelector(
      ".m7da-sectioned-extras"
    );

  if(!box)return;

  [
    "details",
    "card",
    "design",
    "about",
    "hours"
  ].forEach(key=>{
    box.classList.remove(
      "m7v4-extras-"+key
    );
  });

  if(
    [
      "details",
      "card",
      "design",
      "about",
      "hours"
    ].includes(mode)
  ){
    box.classList.add(
      "m7v4-extras-"+mode
    );
  }
}

function applyEditSectionVisibility(panel,mode,shop){
  const form=
    panel?.querySelector(
      "#ma-admin-edit-form"
    );

  if(!form)return;

  const context=
    ensureEditContext(form);

  hideDuplicatePublishingControls(
    form
  );

  hideDuplicateDesignControls(
    form
  );

  configureLegacyExtras(
    form,
    mode
  );

  const all=[
    ...form.children
  ];

  all.forEach(child=>{
    child.classList.remove(
      "m7v4-section-off"
    );
  });

  const specialSelectors=[
    ".m7labelbox",
    ".m7-card-designer-box",
    ".m7-design-studio",
    ".m7-about-services-fields",
    ".m7-about-text-style-box",
    ".m7-hours-schedule-box",
    ".m7-availability-extra-box",
    ".m7da-home-fields",
    ".m7-title-style-box"
  ];

  const specialRoots=
    new Set();

  specialSelectors.forEach(selector=>{
    form
      .querySelectorAll(selector)
      .forEach(node=>{
        const root=
          directFormChild(
            form,
            node
          );

        if(root){
          specialRoots.add(root);
        }
      });
  });

  if(mode==="details"){
    specialRoots.forEach(root=>{
      root.classList.add(
        "m7v4-section-off"
      );
    });

    const extras=
      form.querySelector(
        ".m7da-sectioned-extras"
      );

    if(extras){
      const root=
        directFormChild(
          form,
          extras
        );

      root?.classList.remove(
        "m7v4-section-off"
      );

      expandFocusedSection(
        root
      );
    }
  }
  else{
    all.forEach(child=>{
      if(child!==context){
        child.classList.add(
          "m7v4-section-off"
        );
      }
    });

    const selectors={
      label:[
        ".m7labelbox"
      ],
      card:[
        ".m7-card-designer-box",
        ".m7da-sectioned-extras"
      ],
      design:[
        ".m7-design-studio",
        ".m7da-sectioned-extras"
      ],
      about:[
        ".m7-about-services-fields",
        ".m7-about-text-style-box",
        ".m7da-sectioned-extras"
      ],
      hours:[
        ".m7-hours-schedule-box",
        ".m7-availability-extra-box",
        ".m7da-sectioned-extras"
      ]
    }[mode]||[];

    selectors.forEach(selector=>{
      form
        .querySelectorAll(selector)
        .forEach(node=>{
          const root=
            directFormChild(
              form,
              node
            );

          if(root){
            root.classList.remove(
              "m7v4-section-off"
            );

            expandFocusedSection(root);
          }
        });
    });
  }

  context.classList.remove(
    "m7v4-section-off"
  );

  /*
    Profile Design already has real tabs.
    Keep exactly one pane active instead of showing the whole studio.
  */
  if(mode==="design"){
    const design=
      form.querySelector(
        ".m7-design-studio"
      );

    if(design){
      expandFocusedSection(design);

      const tabs=[
        ...design.querySelectorAll(
          "[data-m7ds-tab]"
        )
      ];

      const panes=[
        ...design.querySelectorAll(
          "[data-m7ds-pane]"
        )
      ];

      let active=
        tabs.find(button=>
          button.classList.contains(
            "active"
          )
        );

      if(!active){
        active=tabs[0]||null;
      }

      const key=
        active?.dataset.m7dsTab||
        "identity";

      tabs.forEach(button=>{
        button.classList.toggle(
          "active",
          button.dataset.m7dsTab===key
        );
      });

      panes.forEach(pane=>{
        pane.classList.toggle(
          "active",
          pane.dataset.m7dsPane===key
        );
      });
    }
  }

  updateEditContext(
    panel,
    mode,
    shop
  );
}

async function openEditMode(slug,mode){
  if(
    typeof window.Ma7alakAdminOpenEditShop!=="function"
  ){
    throw new Error("Core Edit Shop function is not ready yet.");
  }

  const result=
    await client
      .from("shop_profiles")
      .select("*")
      .eq("shop_slug",slug)
      .maybeSingle();

  if(result.error)throw result.error;

  const shop=result.data;

  if(!shop){
    throw new Error("Shop data not found.");
  }

  window.Ma7alakAdminOpenEditShop(shop);

  if(
    typeof window.Ma7alakAdminSyncEditSmartFields==="function"
  ){
    window.Ma7alakAdminSyncEditSmartFields(shop);
  }

  const panel=await waitForEdit(slug);
  if(!panel)throw new Error("Edit Shop panel did not open.");

  showLegacy("ma-admin-edit-card");
  panel.classList.add("m7v4-mode-"+mode);

  mountEditPreview(
    panel,
    mode,
    shop
  );

  applyEditSectionVisibility(
    panel,
    mode,
    shop
  );

  const form=
    panel.querySelector(
      "#ma-admin-edit-form"
    );

  if(
    form &&
    !form.__m7v4SectionObserver
  ){
    form.__m7v4SectionObserver=
      new MutationObserver(()=>{
        applyEditSectionVisibility(
          panel,
          panel.dataset.m7v4PreviewMode||
          mode,
          currentPreviewShop()
        );
      });

    form.__m7v4SectionObserver.observe(
      form,
      {
        childList:true
      }
    );
  }

  const targets={
    label:".m7labelbox",
    card:".m7-card-designer-box",
    about:".m7-about-services-fields",
    hours:".m7-hours-schedule-box",
    design:".m7-design-studio",
    details:".m7v4-edit-context"
  };

  const target=panel.querySelector(targets[mode]||".m7v4-edit-context");
  if(target){
    setTimeout(()=>target.scrollIntoView({behavior:"smooth",block:"center"}),120);
  }

  setTimeout(()=>refreshEditPreview(panel),80);
  setTimeout(()=>refreshEditPreview(panel),260);
}

function previewVal(id,fallback){
  const el=document.getElementById(id);

  if(!el){
    return fallback===undefined
      ? ""
      : fallback;
  }

  return String(
    el.value===undefined
      ? ""
      : el.value
  ).trim();
}

function previewChecked(id,fallback){
  const el=document.getElementById(id);

  return el
    ? !!el.checked
    : !!fallback;
}

function previewColor(id,fallback){
  const raw=previewVal(id,fallback);

  return /^#[0-9a-f]{6}$/i.test(raw)
    ? raw
    : fallback;
}

function previewServiceIcon(value){
  const map={
    hijab:"✦",
    clothing:"👔",
    dress:"👗",
    bag:"👜",
    beauty:"✨",
    perfume:"🌸",
    tattoo:"✒",
    piercing:"💍",
    coffee:"☕",
    food:"🍴",
    delivery:"🚚",
    location:"📍",
    phone:"📱",
    heart:"♡",
    star:"☆",
    sparkle:"✦",
    shop:"🏪"
  };

  return map[String(value||"").toLowerCase()]||"✦";
}

function currentPreviewShop(){
  return selectedShop()||{};
}

function previewAnimClass(value){
  let key=String(value||"").trim().toLowerCase();

  if(key==="current"){
    key="shimmer";
  }

  return [
    "glow",
    "breathe",
    "shimmer",
    "float",
    "pulse",
    "sway",
    "bounce",
    "flicker"
  ].includes(key)
    ? " m7pv-anim m7pv-anim-"+key
    : "";
}

function previewEffectSettings(){
  const speed=
    Math.max(
      .6,
      Math.min(
        6,
        Number(
          previewVal(
            "m7de-page_animation_speed",
            "2.4"
          )
        )||2.4
      )
    );

  const intensity=
    Math.max(
      0,
      Math.min(
        100,
        Number(
          previewVal(
            "m7de-page_animation_intensity",
            "55"
          )
        )||55
      )
    );

  const glow=
    Math.max(
      0,
      Math.min(
        100,
        Number(
          previewVal(
            "m7de-page_glow_power",
            "55"
          )
        )||55
      )
    );

  const shimmer=
    Math.max(
      0,
      Math.min(
        100,
        Number(
          previewVal(
            "m7de-page_shimmer_brightness",
            "75"
          )
        )||75
      )
    );

  const distance=
    Math.max(
      0,
      Math.min(
        20,
        Number(
          previewVal(
            "m7de-page_float_distance",
            "6"
          )
        )||6
      )
    );

  return {
    speed:speed,
    intensity:intensity,
    glow:glow,
    shimmer:shimmer,
    distance:distance
  };
}

function previewAnimStyle(color){
  const fx=previewEffectSettings();
  const alpha=(.2+fx.shimmer*.008).toFixed(2);
  const scale=(1+fx.intensity*.0007).toFixed(4);
  const rotate=(.35+fx.intensity*.02).toFixed(2);
  const floatPx=(fx.distance*(.35+fx.intensity/100)).toFixed(2);
  const glowPx=(2+fx.glow*.18);
  const glowSoft=Math.max(1,glowPx*.35);
  const glowLow=Math.max(1,glowPx*.25);
  const glowFar=Math.max(2,glowPx*1.7);
  const floatNumber=Number(floatPx);
  const rotateNumber=Number(rotate);

  return [
    "--m7-anim-color:"+color,
    "--m7-anim-speed:"+fx.speed+"s",
    "--m7-glow-px:"+glowPx.toFixed(2)+"px",
    "--m7-glow-soft-px:"+glowSoft.toFixed(2)+"px",
    "--m7-glow-low-px:"+glowLow.toFixed(2)+"px",
    "--m7-glow-far-px:"+glowFar.toFixed(2)+"px",
    "--m7-scale-max:"+scale,
    "--m7-rotate-deg:"+rotateNumber.toFixed(2)+"deg",
    "--m7-rotate-neg-deg:"+(-rotateNumber).toFixed(2)+"deg",
    "--m7-float-px:"+floatNumber.toFixed(2)+"px",
    "--m7-float-neg-px:"+(-floatNumber).toFixed(2)+"px",
    "--m7-float-quarter-px:"+(floatNumber*.25).toFixed(2)+"px",
    "--m7-shimmer-color:rgba(255,255,255,"+Math.min(1,Number(alpha))+")"
  ].join(";");
}

function previewSymbol(kind,custom){
  const own=String(custom||"").trim();

  if(kind==="custom"&&own){
    return own.slice(0,5);
  }

  return ({
    diamond:"◆",
    ring:"◇",
    star:"★",
    sparkle:"✦",
    dot:"•",
    circle:"●",
    heart:"♥",
    bolt:"⚡",
    crown:"♛",
    flame:"🔥",
    coffee:"☕",
    flower:"✿",
    moon:"☾",
    plus:"✚",
    chevron:"❯",
    none:""
  })[String(kind||"diamond").toLowerCase()]||"◆";
}

function previewLineStyle(style,color){
  const fx=previewEffectSettings();
  const key=String(style||"fade").toLowerCase();
  const glow=(2+fx.glow*.12).toFixed(1);

  if(key==="none"){
    return "display:none";
  }

  if(key==="solid"){
    return "background:"+color+";box-shadow:0 0 "+glow+"px "+color;
  }

  if(key==="double"){
    return "height:4px;background:linear-gradient(to bottom,"+color+" 0 1px,transparent 1px 3px,"+color+" 3px 4px);box-shadow:0 0 "+glow+"px "+color;
  }

  if(key==="dotted"){
    return "background:radial-gradient(circle,"+color+" 0 1.2px,transparent 1.4px) 0 50% / 7px 3px repeat-x";
  }

  if(key==="dashed"){
    return "background:repeating-linear-gradient(90deg,"+color+" 0 9px,transparent 9px 15px)";
  }

  if(key==="segmented"){
    return "background:repeating-linear-gradient(90deg,"+color+" 0 5px,transparent 5px 8px,"+color+" 8px 16px,transparent 16px 23px)";
  }

  if(key==="gradient"){
    return "background:linear-gradient(90deg,transparent,"+color+",#fff,"+color+",transparent)";
  }

  if(key==="neon"){
    return "background:"+color+";box-shadow:0 0 "+glow+"px "+color+",0 0 "+(Number(glow)*1.8).toFixed(1)+"px "+color;
  }

  if(key==="beam"){
    return "height:3px;background:linear-gradient(90deg,transparent 0 8%,"+color+" 30% 70%,transparent 92%);box-shadow:0 0 "+glow+"px "+color;
  }

  return "background:linear-gradient(90deg,transparent 0%,"+color+" 30%,"+color+" 70%,transparent 100%)";
}

function previewFontFamily(value){
  const families={
    system:'Arial,"Segoe UI",sans-serif',
    modern:'Inter,Arial,"Segoe UI",sans-serif',
    elegant:'Georgia,"Times New Roman",serif',
    classic:'"Times New Roman",Georgia,serif',
    mono:'ui-monospace,SFMono-Regular,Menlo,monospace'
  };

  return families[String(value||"").trim().toLowerCase()]||"inherit";
}

function previewModuleTypography(key){
  const globalFont=
    previewVal(
      "m7de-global_font_style",
      "current"
    );

  const globalSize=
    Math.max(
      70,
      Math.min(
        150,
        Number(
          previewVal(
            "m7de-global_font_size",
            "100"
          )
        )||100
      )
    );

  const moduleFont=
    previewVal(
      "m7de-"+key+"_font_style",
      "inherit"
    );

  const moduleSize=
    Math.max(
      70,
      Math.min(
        150,
        Number(
          previewVal(
            "m7de-"+key+"_font_size",
            String(globalSize)
          )
        )||globalSize
      )
    );

  return {
    family:
      String(moduleFont).toLowerCase()==="inherit"
        ? previewFontFamily(globalFont)
        : previewFontFamily(moduleFont),
    size:moduleSize
  };
}

function previewAboutStyle(key,fallbackColor){
  const row=
    document.querySelector(
      '#ma-admin-edit-form .m7-about-text-style-box [data-m7ats-row="'+CSS.escape(key)+'"]'
    );

  const color=
    row?.querySelector("[data-m7ats-color]")?.value||
    fallbackColor;

  const font=
    String(
      row?.querySelector("[data-m7ats-font]")?.value||
      "inherit"
    );

  const size=
    Math.max(
      60,
      Math.min(
        200,
        Number(
          row?.querySelector("[data-m7ats-size]")?.value||
          100
        )
      )
    );

  return {
    color:color,
    size:size,
    family:previewFontFamily(font)
  };
}

