    hijab:"◒",
    tattoo:"✒",
    piercing:"◈",
    cafe:"☕",
    food:"◉",
    beauty:"✦",
    perfume:"♢",
    phone:"▯",
    barber:"✂",
    gym:"↔",
    kiosk:"▣",
    star:"★",
    heart:"♥",
    sparkle:"✦",
    ring:"◇",
    circle:"●",
    bolt:"⚡",
    crown:"♛",
    flame:"🔥",
    coffee:"☕",
